<script setup>
import {ref} from 'vue';
import axios from 'axios';
import {message} from '../art';
import StudySheet from './StudySheet.vue';
const props=defineProps({questionId:String}),sheet=ref(null),note=ref(''),reason=ref(''),revision=ref(0),busy=ref(false),loaded=ref(false),status=ref(''),failed=ref(false);
async function load(){sheet.value.open();busy.value=true;status.value='';loaded.value=false;failed.value=false;try{const r=await axios.get('/questions/'+props.questionId+'/note',{timeout:20000});note.value=r.data.note;reason.value=r.data.reason;revision.value=r.data.revision;loaded.value=true}catch(e){status.value=message(e);failed.value=true}finally{busy.value=false}}
async function save(){busy.value=true;status.value='';failed.value=false;try{const r=await axios.post('/questions/'+props.questionId+'/note',{note:note.value,reason:reason.value||null,revision:revision.value},{timeout:20000});revision.value=r.data.revision;status.value='Your private note is saved.'}catch(e){status.value=message(e);failed.value=true}finally{busy.value=false}}
</script>
<template><div class="study-note"><button :disabled="busy" @click="load">Make a note</button><StudySheet ref="sheet" title="Private note" :busy="busy"><p class="field-help">{{questionId}} · Only you can see this note.</p><p v-if="busy&&!loaded" role="status">Loading your note…</p><form v-if="loaded" @submit.prevent="save"><label>What happened?<select v-model="reason" :disabled="busy"><option value="">Choose a reason (optional)</option><option value="unknown">I didn't know this</option><option value="confused">I confused two concepts</option><option value="misread">I misread the question</option><option value="guessed">I guessed</option></select></label><label>What will help you remember?<textarea v-model="note" :disabled="busy" maxlength="2000" rows="5" placeholder="Write your own takeaway…"></textarea></label><button :disabled="busy" class="primary">{{busy?'Saving…':'Save note'}}</button></form><p :class="{error:failed}" :role="failed?'alert':'status'">{{status}}</p><button v-if="failed&&!busy" @click="load">Reload saved note</button></StudySheet></div></template>
